/**
 * Checks whether a given source URL is included in the app's authorized Content Security Policy.
 *
 * @param source - The URL to check against the app's CSP allowlist.
 * @returns A promise resolving to `true` if the source is allowed, `false` otherwise.
 * @public
 */
export type IsSourceInAuthorizedCSP = (source: string) => Promise<boolean>;
/** @public */
export declare const isSourceInAuthorizedCSP: IsSourceInAuthorizedCSP;
